inline constexpr double ORACLE_ACC_64 = 1;
inline constexpr double ORACLE_COLL_32 = 0.31999999999999995;
inline constexpr double ORACLE_COLL_128 = 0.16000000000000003;
inline constexpr double ORACLE_ACC_REPEAT = 1;

int dgim_count(const std::vector<int>& stream, int window, double eps) {
    int k = static_cast<int>(1.0 / eps + 0.999999);
    int cap = k / 2 + 1;
    std::vector<std::pair<int, int>> buckets; // (size, timestamp)
    for (size_t t = 0; t < stream.size(); ++t) {
        std::vector<std::pair<int, int>> active;
        for (const auto& b : buckets) {
            if (b.second > static_cast<int>(t) - window) active.push_back(b);
        }
        buckets.swap(active);
        if (stream[t] == 1) {
            buckets.insert(buckets.begin(), {1, static_cast<int>(t)});
            int size = 1;
            while (true) {
                std::vector<size_t> idxs;
                for (size_t i = 0; i < buckets.size(); ++i) {
                    if (buckets[i].first == size) idxs.push_back(i);
                }
                if (idxs.size() <= static_cast<size_t>(cap)) break;
                size_t i2 = idxs.back(); idxs.pop_back();
                size_t i1 = idxs.back();
                int merged_ts = std::max(buckets[i1].second, buckets[i2].second);
                buckets[i1] = {size * 2, merged_ts};
                buckets.erase(buckets.begin() + i2);
                size *= 2;
            }
        }
    }
    if (buckets.empty()) return 0;
    int total = 0;
    for (const auto& b : buckets) total += b.first;
    return total - buckets.back().first / 2;
}

size_t bucket_count(const std::vector<int>& stream, int window, double eps) {
    int k = static_cast<int>(1.0 / eps + 0.999999);
    int cap = k / 2 + 1;
    std::vector<std::pair<int, int>> buckets;
    for (size_t t = 0; t < stream.size(); ++t) {
        std::vector<std::pair<int, int>> active;
        for (const auto& b : buckets) {
            if (b.second > static_cast<int>(t) - window) active.push_back(b);
        }
        buckets.swap(active);
        if (stream[t] == 1) {
            buckets.insert(buckets.begin(), {1, static_cast<int>(t)});
            int size = 1;
            while (true) {
                std::vector<size_t> idxs;
                for (size_t i = 0; i < buckets.size(); ++i) {
                    if (buckets[i].first == size) idxs.push_back(i);
                }
                if (idxs.size() <= static_cast<size_t>(cap)) break;
                size_t i2 = idxs.back(); idxs.pop_back();
                size_t i1 = idxs.back();
                int merged_ts = std::max(buckets[i1].second, buckets[i2].second);
                buckets[i1] = {size * 2, merged_ts};
                buckets.erase(buckets.begin() + i2);
                size *= 2;
            }
        }
    }
    return buckets.size();
}

int main() {
    const int N = 1000;
    const double eps = 0.1;
    const auto& stream = ORACLE_STREAM;

    int est = dgim_count(stream, N, eps);
    int true_count = 0;
    for (int i = static_cast<int>(stream.size()) - N; i < static_cast<int>(stream.size()); ++i) {
        true_count += stream[i];
    }
    double rel = std::fabs(static_cast<double>(est - true_count)) / true_count;
    std::cout << "DGIM windowed count: est=" << est
              << ", true=" << true_count
              << ", rel_err=" << rel
              << " (eps=" << eps << ")" << std::endl;

    assert(rel <= eps + 1e-9);
    assert(bucket_count(stream, N, eps) < static_cast<size_t>(N / 10));

    std::cout << "Exponential histogram (DGIM) PASS" << std::endl;
    return 0;
}